  const n = (70 * Math.sin(x * 0.0009 + 1.3) + 50 * Math.sin(z * 0.0013 - x * 0.0004)) * sm(900, 1700, Math.abs(x)) * (sm(-1300, -2600, z) - sm(-5000, -5900, z));
  return -350 * sm(2250, 2650, z) + S.TOP * sm(-1300, -5900, z) + n;
};
S.waters = [];
S.water = (w, d, col, rep = 700, op = 0.9) => { // a water surface with ripples that move (S.waters)
