  cx.fillStyle = col; cx.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 80; i++) {
    const y = (i * 37) % 256, x = (i * 91) % 256, l = 30 + (i * 13) % 60;
    cx.strokeStyle = 'rgba(255,255,255,' + (0.05 + (i % 5) * 0.025) + ')'; cx.lineWidth = 1 + (i % 3);
    for (const ox of [0, -256]) { cx.beginPath(); cx.moveTo(x + ox, y); cx.quadraticCurveTo(x + ox + l / 2, y - 4, x + ox + l, y); cx.stroke(); }
  }
