// Inside one pump, its casing cut open: the impeller (curved vanes) turns about 1,000 times a minute (shown slowed). The
// water comes in at the eye (the middle), the vanes fling it outward, the spiral casing (the volute) gathers it, slows it
// and turns its speed into pressure: up the outlet it goes, strong enough to climb 25 m of hill.
const blue = W.paint('#2f5f8f', { metallic: 0.3, rough: 0.5 }), bronze = W.metal('#b0874a', { rough: 0.35 }), steel = W.metal('#c3c8cc', { rough: 0.35 });
const glassy = new THREE.MeshStandardMaterial({ color: 0x9fc6e0, roughness: 0.2, metalness: 0, transparent: true, opacity: 0.18, depthWrite: false });
const vol = W.group();
vol.add(W.mesh(W.cyl(190, 190, 10, 48), blue, { at: [0, 0, -45], rot: [90, 0, 0] }));
const spiral = [];
for (let i = 0; i <= 48; i++) { const a = (i / 48) * Math.PI * 2, r = 128 + 52 * (i / 48); spiral.push([Math.cos(a) * (r + 10), Math.sin(a) * (r + 10)]); }
for (let i = 48; i >= 0; i--) { const a = (i / 48) * Math.PI * 2, r = 128 + 52 * (i / 48); spiral.push([Math.cos(a) * r, Math.sin(a) * r]); }
vol.add(W.mesh(W.extrude(spiral, 80), blue, { at: [0, 0, 0] }));
vol.add(W.mesh(W.box(62, 230, 80), blue, { at: [216, 105, 0] }), W.mesh(W.box(10, 230, 80), blue, { at: [148, 125, 0] }));
vol.add(W.mesh(W.cyl(190, 190, 6, 48), glassy, { at: [0, 0, 45], rot: [90, 0, 0] }));
W.add(vol, { label: 'వాల్యూట్ కేసింగ్' });
const imp = W.group();
imp.add(W.mesh(W.cyl(34, 40, 70, 24), bronze, { rot: [90, 0, 0] }), W.mesh(W.cyl(118, 118, 6, 40), bronze, { at: [0, 0, -34], rot: [90, 0, 0] }));
for (let k = 0; k < 6; k++) {
  const vane = [];
  for (let i = 0; i <= 10; i++) { const u = i / 10, r = 40 + 76 * u, a = -u * 1.1; vane.push([Math.cos(a) * r, Math.sin(a) * r]); }
  for (let i = 10; i >= 0; i--) { const u = i / 10, r = 40 + 76 * u, a = -u * 1.1 + 0.12; vane.push([Math.cos(a) * r, Math.sin(a) * r]); }
  const m = W.mesh(W.extrude(vane, 60), bronze, { at: [0, 0, -2] }); m.rotation.z = (k / 6) * Math.PI * 2; imp.add(m);
}
W.add(imp, { label: 'ఇంపెల్లర్' });
const sh = W.group();
sh.add(W.mesh(W.cyl(22, 22, 260, 20), steel, { at: [0, 0, -170], rot: [90, 0, 0] }));
W.add(sh, { label: 'షాఫ్ట్' });
const N = 140, drops = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 8, 6), new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.3 }), N);
const dg = W.group(); dg.add(drops);
W.add(dg, { label: 'నీరు' });
const u = Array.from({ length: N }, (_, i) => i / N), ph = Array.from({ length: N }, (_, i) => (i * 0.618) % 1);
const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), P = new THREE.Vector3(), Z = new THREE.Vector3(), C = new THREE.Color();
let spin = 0;
W.onTick((t, dt) => {
  const k = 0.35 + 0.65 * Math.max(0.15, W.env.spool);
  spin += dt * 2.2 * k; imp.rotation.z = -spin;
  for (let i = 0; i < N; i++) {
    u[i] = (u[i] + dt * 0.16 * k) % 1;
    const v = u[i], a0 = ph[i] * Math.PI * 2;
    if (v < 0.2) P.set(Math.cos(a0) * 20, Math.sin(a0) * 20, 200 - 900 * v); // (in at the eye, from the front)
    else if (v < 0.5) { const w = (v - 0.2) / 0.3, a = a0 - spin * 0.6 - w * 1.4, r = 30 + 90 * w; P.set(Math.cos(a) * r, Math.sin(a) * r, 0); } // (flung out by the vanes)
    else if (v < 0.85) { const w = (v - 0.5) / 0.35, a = -w * Math.PI * 1.6 + a0 * 0.2, r = 135 + 35 * w; P.set(Math.cos(a) * r, Math.sin(a) * r, (ph[i] - 0.5) * 50); } // (round the volute)
    else { const w = (v - 0.85) / 0.15; P.set(205 + (ph[i] - 0.5) * 30, 10 + 230 * w, (ph[i] - 0.5) * 50); } // (up the outlet)
    M.compose(P, Q, Z.setScalar(5 + 3 * Math.min(1, v * 2)));
    drops.setMatrixAt(i, M);
    drops.setColorAt(i, C.setHSL(0.55, 0.7, 0.75 - 0.35 * v));
  }
  drops.instanceMatrix.needsUpdate = true;
  if (drops.instanceColor) drops.instanceColor.needsUpdate = true;
});
